-- ============================================================================
-- superi.ge — 38: საკერავი მანქანების კამპანია (ატვირთეთ სტატიის გამოქვეყნების შემდეგ!)
-- 1) კატეგორია „საკერავი ტექნიკა“ → „საკერავი მანქანები“ (H1, სათაური, ბრედქრამბი, მენიუ). მისამართი /sakeravi-teqnika/ არ იცვლება.
--    + სრული ტექსტი (შერჩევის რჩევები, პოპულარული მოდელები, კითხვა-პასუხი, ბმული სტატიაზე) + მეტა აღწერა.
-- 2) 53 პროდუქტი — უნიკალური მეტა აღწერა რეალური მახასიათებლებით (160 სიმბოლომდე).
-- 3) სახელები: „საკერაივ“ → „საკერავი“ (Janome XE 300); „ავერლოკის მანქანა“ → „ოვერლოკი“ (Leader VS 330D / VS 390D).
-- 4) აღწერებში შეცდომები: რეგურილება, სილძლავრე, ზოგზაგის, ავტომატრუი, ავერლოკი, რუსული სიტყვები (лапკის, распошивочный, შტოპვის…) და სხვ.;
--    Brother Innov-is F460 — ტიპი „ელექტრომექანიკური“ → „კომპიუტერიზებული“.
-- 5) Janome J925S-ს ბრენდი აკლდა → ემატება JANOME (ჩანს /janome/ გვერდზე და ფილტრში).
-- 6) საიტის ძებნის სინონიმები: საკერავი მანქანები, ჯანომე, სინგერი/ზინგერი, ბრაზერი, ბერნეტი, ავერლოკი/оверлок.
-- ასლები: superi_bk_cat_38, superi_bk_prod_38, superi_bk_menu_38, superi_bk_feat_38. ხელახლა გაშვება უსაფრთხოა. დაბრუნება ბოლოშია.
-- ატვირთვის შემდეგ: Live search → Synonyms → „Rebuild synonym index“ → ქეშის გასუფთავება.
-- ============================================================================
SET NAMES utf8mb4;

-- 0) ასლები
CREATE TABLE IF NOT EXISTS superi_bk_cat_38 AS SELECT cd.category_id, cd.lang_code, cd.category, cd.description, cd.meta_description, cd.page_title FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' WHERE cd.lang_code = 'ka';
CREATE TABLE IF NOT EXISTS superi_bk_prod_38 AS SELECT pd.product_id, pd.lang_code, pd.product, pd.page_title, pd.meta_description, pd.full_description FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 WHERE pd.lang_code = 'ka' AND s.name IN ('bernette-sew-and-go-3', 'bernette-sew-and-go-5', 'brother-artwork-33a', 'brother-artwork-37a', 'brother-elite-45', 'brother-elite-55', 'brother-innov-is-f460', 'brother-js27', 'brother-modern-210e', 'brother-okinawa', 'brother-st55e', 'brother-vitrage-m77', 'brother-xn2500', 'janome-1225s', 'janome-1522bl', 'janome-1522dg', 'janome-1522pg', 'janome-1543', 'janome-1547', 'janome-2121', 'janome-2252', 'janome-311pg', 'janome-4100l', 'janome-718a', 'janome-anna', 'janome-artdecor-724a', 'janome-artstyle-4045', 'janome-clio-320', 'janome-clio-325', 'janome-color-55', 'janome-dc3900', 'janome-hd1019', 'janome-hd1023', 'janome-hd6130', 'janome-high-style-1818', 'janome-homedecor-2077', 'janome-homedecor-2320', 'janome-j925s', 'janome-jl-23', 'janome-ml77', 'janome-mx-1717', 'janome-mx55', 'janome-my-excel-18w', 'janome-pink-25', 'janome-se-7519', 'janome-se-7522', 'janome-smart2119', 'janome-xe-300', 'leader-vs-330d', 'leader-vs-390d', 'singer-simple-3210', 'singer-standard-smc-8280-00', 'singer-start-1306');
CREATE TABLE IF NOT EXISTS superi_bk_menu_38 AS SELECT param_id, lang_code, descr FROM cscart_static_data_descriptions WHERE lang_code = 'ka' AND descr = 'საკერავი ტექნიკა';
SET @j925 := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name = 'janome-j925s' LIMIT 1);
CREATE TABLE IF NOT EXISTS superi_bk_feat_38 AS SELECT * FROM cscart_product_features_values WHERE product_id = @j925;

-- 1) კატეგორია: სახელი, ტექსტი, მეტა აღწერა; მენიუს პუნქტი
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' SET cd.category = 'საკერავი მანქანები' WHERE cd.lang_code = 'ka' AND cd.category = 'საკერავი ტექნიკა';
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' SET cd.page_title = '' WHERE cd.lang_code = 'ka' AND cd.page_title IN ('საკერავი ტექნიკა', 'საკერავი ტექნიკა — საუკეთესო ფასები | Superi.ge');
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' SET cd.description = '<p><strong>საკერავი მანქანა</strong> სახლში ყველაზე საჭირო ტექნიკაა ტანსაცმლის შესაკეთებლად, შარვლის დასამოკლებლად, ფარდებისა და თეთრეულის შესაკერად და საკუთარი ნამუშევრების შესაქმნელად. Superi.ge-ზე იპოვით 50-ზე მეტ საკერავ მანქანას — <a href="https://superi.ge/janome/">Janome</a>, <a href="https://superi.ge/brother/">Brother</a>, <a href="https://superi.ge/singer/">Singer</a> და <a href="https://superi.ge/bernette/">Bernette</a> — მარტივი ელექტრომექანიკური მოდელებიდან კომპიუტერიზებულ მანქანებამდე, ასევე ოვერლოკებს ქსოვილის კიდის დასამუშავებლად.</p><h2>როგორ შევარჩიოთ საკერავი მანქანა</h2><ul><li><strong>ელექტრომექანიკური თუ კომპიუტერიზებული:</strong> ელექტრომექანიკური მანქანა სახელურებით იმართება — მარტივი, საიმედო და ხელმისაწვდომია, იდეალურია დამწყებისთვის და ყოველდღიური კერვისთვის. კომპიუტერიზებულს აქვს ეკრანი, ბევრი ნაკერი, რამდენიმე ავტომატური ღილკილო და Start/Stop ღილაკი — შეგიძლიათ პედლის გარეშეც კეროთ.</li><li><strong>ოპერაციების რაოდენობა:</strong> სახლისთვის 15–25 ოპერაცია სავსებით საკმარისია: სწორი ნაკერი, ზიგზაგი, ფარული, ელასტიური და ოვერლოკის ნაკერები. 50–200 ოპერაცია დეკორატიული კერვისა და შემოქმედებითი სამუშაოებისთვის გამოგადგებათ.</li><li><strong>ღილკილო:</strong> ავტომატურ ღილკილოს მანქანა ერთ ეტაპად აკეთებს, ღილის ზომის მიხედვით. ნახევრად ავტომატურს 4 ეტაპად, სახელურის გადართვით — ესეც მარტივია, უბრალოდ მეტ დროს მოითხოვს.</li><li><strong>მაქო:</strong> ჰორიზონტალური მაქო ჩუმია, კოჭა ზემოდან იდება და ძაფის ნაშთი ჩანს. ვერტიკალური მაქო საიმედო და გამძლეა, მას ბევრი კლასიკური მოდელი იყენებს.</li><li><strong>სქელი ქსოვილები:</strong> ჯინსის, ტყავისა და ფარდის ქსოვილისთვის აირჩიეთ ლითონის კარკასიანი, გაძლიერებული მოდელი — მაგ. <a href="https://superi.ge/janome-hd1019/">Janome HD1019</a>, <a href="https://superi.ge/janome-smart2119/">Janome Smart2119</a> ან <a href="https://superi.ge/janome-my-excel-18w/">Janome My Excel 18W</a>.</li><li><strong>მოხერხებულობა:</strong> ძაფის ჩამყრელი, ძაფის საჭრელი, LED განათება და თავისუფალი სახელო (სახელოებისა და შარვლის ტოტების შესაკერად) ყოველდღიურ მუშაობას საგრძნობლად ამარტივებს.</li></ul><h2>პოპულარული საკერავი მანქანები</h2><ul><li><strong>დამწყებისთვის:</strong> <a href="https://superi.ge/brother-js27/">Brother JS27</a>, <a href="https://superi.ge/janome-311pg/">Janome 311PG</a>, <a href="https://superi.ge/janome-jl-23/">Janome JL-23</a>, <a href="https://superi.ge/janome-color-55/">Janome Color 55</a>, <a href="https://superi.ge/singer-start-1306/">Singer Start 1306</a>.</li><li><strong>უნივერსალური, ავტომატური ღილკილოთი:</strong> <a href="https://superi.ge/janome-j925s/">Janome J925S</a>, <a href="https://superi.ge/janome-anna/">Janome ANNA</a>, <a href="https://superi.ge/janome-1522bl/">Janome 1522BL</a>, <a href="https://superi.ge/bernette-sew-and-go-5/">Bernette Sew&amp;Go 5</a>, <a href="https://superi.ge/brother-artwork-37a/">Brother Artwork 37A</a>.</li><li><strong>სქელი ქსოვილებისთვის:</strong> <a href="https://superi.ge/janome-hd1019/">Janome HD1019</a>, <a href="https://superi.ge/janome-hd1023/">Janome HD1023</a>, <a href="https://superi.ge/janome-artdecor-724a/">Janome ArtDecor 724A</a>.</li><li><strong>კომპიუტერიზებული:</strong> <a href="https://superi.ge/janome-4100l/">Janome 4100L</a>, <a href="https://superi.ge/brother-modern-210e/">Brother Modern 210E</a>, <a href="https://superi.ge/brother-st55e/">Brother ST55E</a>, <a href="https://superi.ge/brother-innov-is-f460/">Brother Innov-is F460</a>.</li><li><strong>ოვერლოკები:</strong> <a href="https://superi.ge/leader-vs-330d/">Leader VS 330D</a> (3/4 ძაფი) და <a href="https://superi.ge/leader-vs-390d/">Leader VS 390D</a> (2–5 ძაფი, კოვერლოკის ფუნქციით).</li></ul><h2>ხშირად დასმული კითხვები</h2><h3>რომელი საკერავი მანქანა ჯობია დამწყებისთვის?</h3><p>დამწყებისთვის საუკეთესოა ელექტრომექანიკური მანქანა 15–25 ოპერაციით, LED განათებითა და ძაფის საჭრელით. ის მარტივი სამართავია და ყველა ძირითად სამუშაოს ასრულებს — შეკეთებას, დამოკლებას, ელვის ჩაკერებას.</p><h3>რა განსხვავებაა საკერავ მანქანასა და ოვერლოკს შორის?</h3><p>საკერავი მანქანა ქსოვილს კერავს, ოვერლოკი კი ერთდროულად კერავს, ჭრის და კიდეს ამუშავებს, რომ არ დაიშალოს — როგორც მაღაზიის ტანსაცმელზე. ოვერლოკი საკერავ მანქანას ავსებს და არ ცვლის; ტრიკოტაჟისთვის განსაკუთრებით სასარგებლოა.</p><h3>შეკერავს საკერავი მანქანა ჯინსს?</h3><p>დიახ, თითქმის ყველა მოდელი კერავს ჯინსს ჯინსის ნემსით (№100–110) და დაბალი სიჩქარით. ხშირი და სქელი კერვისთვის ჯობია ლითონის კარკასიანი მოდელი, მაგ. Janome HD სერია.</p><h3>შემიძლია ნაწილ-ნაწილ ყიდვა?</h3><p>დიახ, Superi.ge-ზე საკერავი მანქანის შეძენა შეგიძლიათ ნაწილ-ნაწილ გადახდით. თბილისში მიწოდება უფასოა 100₾-დან, ასევე ვაწვდით მთელ საქართველოში.</p><p>დეტალური რჩევებისთვის წაიკითხეთ ჩვენი გზამკვლევი: <a href="https://superi.ge/rogor-shevarchiot-sakeravi-manqana/">როგორ შევარჩიოთ საკერავი მანქანა</a>.</p>' WHERE cd.lang_code = 'ka';
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' SET cd.meta_description = 'საკერავი მანქანები Janome, Brother, Singer და Bernette — 50+ მოდელი დამწყებისთვის და პროფესიონალისთვის, ოვერლოკები. ✓ ნაწილ-ნაწილ გადახდა ✓ მიწოდება' WHERE cd.lang_code = 'ka';
UPDATE cscart_static_data_descriptions SET descr = 'საკერავი მანქანები' WHERE lang_code = 'ka' AND descr = 'საკერავი ტექნიკა';

-- 2) პროდუქტების მეტა აღწერები (53)
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bernette-sew-and-go-3' SET pd.meta_description = 'საკერავი მანქანა Bernette Sew&Go 3 — 19 ოპერაცია, ნახევრად ავტომატური ღილკილო, ძაფის ჩამყრელი, LED. კერავს ჯინსს, ტყავსა და ტრიკოტაჟს. ✓ ნაწილ-ნაწილ გადახდა' WHERE pd.lang_code = 'ka';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bernette-sew-and-go-5' SET pd.meta_description = 'საკერავი მანქანა Bernette Sew&Go 5 — 23 ოპერაცია, ავტომატური ღილკილო, ძაფის ჩამყრელი, LED. ჯინსის, ტყავისა და ტრიკოტაჟისთვის. ✓ ნაწილ-ნაწილ გადახდა ✓ მიწოდება' WHERE pd.lang_code = 'ka';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'brother-artwork-33a' SET pd.meta_description = 'საკერავი მანქანა Brother Artwork 33A — 27 ოპერაცია, ჰორიზონტალური მაქო, ღილკილო 1 ეტაპად, ძაფის ჩამყრელი, ორმაგი ნემსი, LED. ✓ ნაწილ-ნაწილ გადახდა ✓ მიწოდება' WHERE pd.lang_code = 'ka';
