-- 5) Janome J925S — ბრენდი JANOME (იგივე ჩანაწერი, რაც Janome ML77-ს აქვს)
SET @ref := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name = 'janome-ml77' LIMIT 1);
SET @jv := (SELECT fv.variant_id FROM cscart_product_features_values fv JOIN cscart_product_features f ON f.feature_id = fv.feature_id AND f.feature_type = 'E' WHERE fv.product_id = @ref AND fv.variant_id > 0 LIMIT 1);
INSERT IGNORE INTO cscart_product_features_values (feature_id, product_id, variant_id, value, value_int, lang_code) SELECT fv.feature_id, @j925, fv.variant_id, fv.value, fv.value_int, fv.lang_code FROM cscart_product_features_values fv WHERE fv.product_id = @ref AND fv.variant_id = @jv AND @j925 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_product_features_values x WHERE x.product_id = @j925 AND x.feature_id = fv.feature_id AND x.lang_code = fv.lang_code);

