INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'საკერავი მანქანა', '["საკერავი მანქანები","საკერავი აპარატი","საკერი მანქანა","швейная машина","швейная машинка","sewing machine"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'საკერავი მანქანა');
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'საკერავი მანქანა' ORDER BY synonym_id LIMIT 1);
