INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'ავერლოკი' AS word UNION ALL SELECT 'оверлок' UNION ALL SELECT 'overlock' UNION ALL SELECT 'ოვერლოკის მანქანა' UNION ALL SELECT 'ოვერლოკი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);

-- 7) შემოწმება
SELECT s.name AS slug, cd.category, CHAR_LENGTH(REGEXP_REPLACE(IFNULL(cd.description, ''), '<[^>]*>', '')) AS text_chars, cd.description LIKE '%rogor-shevarchiot-sakeravi-manqana%' AS has_guide_link, CHAR_LENGTH(cd.meta_description) AS meta_chars FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'sakeravi-teqnika' WHERE cd.lang_code = 'ka';
SELECT COUNT(*) AS products, SUM(pd.meta_description LIKE '%✓ ნაწილ-ნაწილ გადახდა%') AS new_metas, MAX(CHAR_LENGTH(pd.meta_description)) AS max_meta_chars FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 WHERE pd.lang_code = 'ka' AND s.name IN ('bernette-sew-and-go-3', 'bernette-sew-and-go-5', 'brother-artwork-33a', 'brother-artwork-37a', 'brother-elite-45', 'brother-elite-55', 'brother-innov-is-f460', 'brother-js27', 'brother-modern-210e', 'brother-okinawa', 'brother-st55e', 'brother-vitrage-m77', 'brother-xn2500', 'janome-1225s', 'janome-1522bl', 'janome-1522dg', 'janome-1522pg', 'janome-1543', 'janome-1547', 'janome-2121', 'janome-2252', 'janome-311pg', 'janome-4100l', 'janome-718a', 'janome-anna', 'janome-artdecor-724a', 'janome-artstyle-4045', 'janome-clio-320', 'janome-clio-325', 'janome-color-55', 'janome-dc3900', 'janome-hd1019', 'janome-hd1023', 'janome-hd6130', 'janome-high-style-1818', 'janome-homedecor-2077', 'janome-homedecor-2320', 'janome-j925s', 'janome-jl-23', 'janome-ml77', 'janome-mx-1717', 'janome-mx55', 'janome-my-excel-18w', 'janome-pink-25', 'janome-se-7519', 'janome-se-7522', 'janome-smart2119', 'janome-xe-300', 'leader-vs-330d', 'leader-vs-390d', 'singer-simple-3210', 'singer-standard-smc-8280-00', 'singer-start-1306');
SELECT s.name AS slug, pd.product FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 WHERE pd.lang_code = 'ka' AND s.name IN ('janome-xe-300', 'leader-vs-330d', 'leader-vs-390d');
SELECT COUNT(*) AS typos_left FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 WHERE pd.lang_code = 'ka' AND s.name IN ('bernette-sew-and-go-3', 'bernette-sew-and-go-5', 'brother-artwork-33a', 'brother-artwork-37a', 'brother-elite-45', 'brother-elite-55', 'brother-innov-is-f460', 'brother-js27', 'brother-modern-210e', 'brother-okinawa', 'brother-st55e', 'brother-vitrage-m77', 'brother-xn2500', 'janome-1225s', 'janome-1522bl', 'janome-1522dg', 'janome-1522pg', 'janome-1543', 'janome-1547', 'janome-2121', 'janome-2252', 'janome-311pg', 'janome-4100l', 'janome-718a', 'janome-anna', 'janome-artdecor-724a', 'janome-artstyle-4045', 'janome-clio-320', 'janome-clio-325', 'janome-color-55', 'janome-dc3900', 'janome-hd1019', 'janome-hd1023', 'janome-hd6130', 'janome-high-style-1818', 'janome-homedecor-2077', 'janome-homedecor-2320', 'janome-j925s', 'janome-jl-23', 'janome-ml77', 'janome-mx-1717', 'janome-mx55', 'janome-my-excel-18w', 'janome-pink-25', 'janome-se-7519', 'janome-se-7522', 'janome-smart2119', 'janome-xe-300', 'leader-vs-330d', 'leader-vs-390d', 'singer-simple-3210', 'singer-standard-smc-8280-00', 'singer-start-1306') AND (pd.full_description LIKE '%რეგურილება%' OR pd.full_description LIKE '%სილძლავრე%' OR pd.full_description LIKE '%ზოგზაგის%' OR pd.full_description LIKE '%ავტომატრუი%' OR pd.full_description LIKE '%ავერლოკ%' OR pd.full_description LIKE '%დეკოტარიული%' OR pd.full_description LIKE '%სიჩქრე%' OR pd.full_description LIKE '%პლატმფორმა%' OR pd.full_description LIKE '%ავტომტური%' OR pd.full_description LIKE '%პოზციონირების%' OR pd.full_description LIKE '%ელექტრონიული%' OR pd.full_description LIKE '%კომპიუტერიზირებული%' OR pd.full_description LIKE '%პიზიციების%' OR pd.full_description LIKE '%ვერტიკალურ როტორული%' OR pd.full_description LIKE '%ზიგზაგის მაქსიმალური სიგრძე%' OR pd.full_description LIKE '%лапკის%' OR pd.full_description LIKE '%распошივочный ნაკერი%' OR pd.full_description LIKE '%სახელოსნო პლატფორმა%' OR pd.full_description LIKE '%მერჟკის ნაკერი%' OR pd.full_description LIKE '%შტოპვის ფირფიტა%' OR pd.full_description LIKE '%ნახევრადავტომატური%');
SELECT COUNT(*) AS j925s_brand_rows FROM cscart_product_features_values WHERE product_id = @j925 AND variant_id = @jv;
SELECT phrase, synonyms FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase IN ('საკერავი მანქანა', 'janome', 'singer', 'brother', 'bernette', 'ოვერლოკი');

